 if(layer==='wind')for(let j=0;j<e.wind.length;j++)for(let i=0;i<e.wind[0].length;i++)rect([(i+.5)*e.wind_dx,(j+.5)*e.wind_dx],e.wind_dx,color(Math.hypot(...e.wind[j][i])/18,blue));
 else if(frame){let max=task?Math.max(...task.weights,1e-9):1;e.cells.forEach((p,j)=>{const k=e.free_indices[j];let v=layer==='clarity'?frame.q[j]:layer==='deficit'?Math.max(e.targets[j]-frame.q[j],0)/.7:layer==='uncertainty'?(belief?.std[k]||0)/1.8:layer==='task'?(task?.weights[k]||0)/max:Math.hypot(...(belief?.mean[k]||[0,0]))/18;rect(p,e.dx,color(v,['uncertainty','belief'].includes(layer)?blue:colors))})}
