 for(const r of regions){ctx.fillStyle='rgba(255,255,255,.12)';ctx.strokeStyle='#6f8e82';ctx.lineWidth=.018;ctx.fillRect(r.bounds[0][0],r.bounds[0][1],r.bounds[1][0]-r.bounds[0][0],r.bounds[1][1]-r.bounds[0][1]);ctx.strokeRect(r.bounds[0][0],r.bounds[0][1],r.bounds[1][0]-r.bounds[0][0],r.bounds[1][1]-r.bounds[0][1])}
